package com.devaxo.templeoftheaxolotl.mixin;

import com.devaxo.templeoftheaxolotl.client.CelestialWaterMode;
import net.minecraft.client.renderer.LevelRenderer;
import org.spongepowered.asm.mixin.Mixin;
import org.spongepowered.asm.mixin.injection.Constant;
import org.spongepowered.asm.mixin.injection.ModifyConstant;

/**
 * Changes the star geometry generated by Minecraft's OWN sky renderer.
 * No AFTER_SKY event, camera quad, overlay, custom aurora or extra draw pass.
 *
 * Star vertices remain part of the vanilla celestial sky buffer and therefore
 * inherit the game's normal sky rotation, weather, time and brightness rules.
 *
 * Mapping-dependent constants: require=0 deliberately prevents a startup
 * crash if Minecraft changes the drawStars implementation. Check the mixin
 * audit/log and visually confirm density after compiling.
 */
@Mixin(LevelRenderer.class)
public abstract class CelestialVanillaStarsMixin {
    @ModifyConstant(method = "drawStars", constant = @Constant(intValue = 1500), require = 0)
    private int tota$moreNaturalStars(int vanillaCount) {
        return true ? 6500 : vanillaCount;
    }

    @ModifyConstant(method = "drawStars", constant = @Constant(floatValue = 0.15F), require = 0)
    private float tota$smallerStarBase(float vanillaSize) {
        return true ? 0.115F : vanillaSize;
    }

    @ModifyConstant(method = "drawStars", constant = @Constant(floatValue = 0.1F), require = 0)
    private float tota$smallerStarVariation(float vanillaVariation) {
        return true ? 0.080F : vanillaVariation;
    }
}
